(()=>{
 const d=window.SF2CESHADOWDATA,cache=new Map(),images=d.frames.map(pair=>pair.map(f=>{
   if(!f)return null;const image=new Image();image.src=f.png;return {...f,image};
 }));
 const ready=Promise.all(images.flat().filter(Boolean).map(f=>f.image.decode()));
 function frame(p,stage){
   if(!p.anim||!Number.isInteger(p.anim.source))return null;
   const raw=d.selectors[p.anim.source+24*p.aidx];if(!raw)return null;
   const selector=raw&127,f=images[selector]&&images[selector][p.FACE?1:0];
   if(!f||!f.image.complete||!f.image.naturalWidth)return null;
   const color=d.colors[stage];if(!color)return null;
   const key=selector+':'+(p.FACE?1:0)+':'+stage;let image=cache.get(key);
   if(!image){image=document.createElement('canvas');image.width=f.w;image.height=f.h;
     const c=image.getContext('2d');c.drawImage(f.image,0,0);c.globalCompositeOperation='source-in';
     c.fillStyle='rgb('+color.join(',')+')';c.fillRect(0,0,f.w,f.h);cache.set(key,image);}
   return {image,x:f.x,y:f.y,w:f.w,h:f.h,selector,source:f.source};
 }
 window.SF2CESHADOW={ready,frame,data:d};
})();
